package com.aabhix.camera;
import android.app.*;import android.content.*;import android.net.Uri;import com.aabhix.camera.domain.PortableConfig;import java.io.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.function.Consumer;
public final class ConfigLibrary {
    private final CameraController camera;private final Activity activity;private final Consumer<PortableConfig> apply;private final File directory;
    public ConfigLibrary(Activity activity,Consumer<PortableConfig> apply,CameraController camera){this.camera=camera;this.activity=activity;this.apply=apply;directory=new File(activity.getFilesDir(),"configurations");directory.mkdirs();}
    public void show(){File[] files=directory.listFiles((d,name)->name.endsWith(".xml"));if(files==null)files=new File[0];Arrays.sort(files,Comparator.comparing(File::getName));List<String> names=new ArrayList<>();names.add("Import XML configuration…");names.add("Save current setup");for(File file:files){try{names.add(new String(java.nio.file.Files.readAllBytes(new File(file.getPath()+".title").toPath()),StandardCharsets.UTF_8));}catch(Exception e){names.add(file.getName());}}File[] chosen=files;new AlertDialog.Builder(activity).setTitle("Configurations · local profiles").setItems(names.toArray(new String[0]),(d,i)->{if(i==0){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);activity.startActivityForResult(intent,31);}else if(i==1)saveCurrent();else readFile(chosen[i-2]);}).setNegativeButton("Close",null).show();}
    public void importUri(Uri uri){new Thread(()->{try(InputStream input=activity.getContentResolver().openInputStream(uri)){if(input==null)throw new IOException("File unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();byte[] chunk=new byte[8192];int n;while((n=input.read(chunk))!=-1){if(bytes.size()+n>2_000_000)throw new IOException("Config exceeds2 MB");bytes.write(chunk,0,n);}String xml=bytes.toString(StandardCharsets.UTF_8.name());PortableConfig config=PortableConfig.parse(xml);String title="Imported XML";try(android.database.Cursor cursor=activity.getContentResolver().query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cursor!=null&&cursor.moveToFirst())title=cursor.getString(0);}store(title,xml);activity.runOnUiThread(()->review(config));}catch(Exception e){error(e);}},"AabhixConfigImport").start();}
    private void readFile(File file){new Thread(()->{try{PortableConfig config=PortableConfig.parse(new String(java.nio.file.Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8));activity.runOnUiThread(()->review(config));}catch(Exception e){error(e);}},"AabhixConfigRead").start();}
    private void review(PortableConfig config){review(config,0);} private void review(PortableConfig config,int attempt){if(activity.isFinishing()||activity.isDestroyed())return;if(!activity.hasWindowFocus()){if(attempt<15)activity.getWindow().getDecorView().postDelayed(()->review(config,attempt+1),200);return;}AlertDialog.Builder dialog=new AlertDialog.Builder(activity).setTitle("Review mapped configuration").setMessage(config.summary()).setNegativeButton("Close",null);if(!config.values.isEmpty())dialog.setPositiveButton("Apply mapped values",(d,i)->apply.accept(config));dialog.show();}
    public void store(String title,String xml)throws Exception{PortableConfig.parse(xml);byte[] digest=MessageDigest.getInstance("SHA-256").digest(xml.getBytes(StandardCharsets.UTF_8));StringBuilder id=new StringBuilder();for(byte value:digest)id.append(String.format(Locale.ROOT,"%02x",value&255));File file=new File(directory,id+".xml");try(OutputStream out=new FileOutputStream(file)){out.write(xml.getBytes(StandardCharsets.UTF_8));}try(OutputStream out=new FileOutputStream(new File(file.getPath()+".title"))){out.write(title.substring(0,Math.min(120,title.length())).getBytes(StandardCharsets.UTF_8));}}
    private void saveCurrent(){try{android.content.SharedPreferences prefs=activity.getSharedPreferences("settings",0);StringBuilder xml=new StringBuilder("<aabhix-config>");for(String key:new String[]{"grid","stableVideo","stabilization"})xml.append("<boolean name='aabhix.").append(key).append("' value='").append(prefs.getBoolean(key,!key.equals("grid"))).append("'/>");xml.append("<int name='aabhix.jpegQuality' value='").append(prefs.getInt("jpegQuality",96)).append("'/>");for(String key:new String[]{"photoFrame","videoFrame"}){String frame=prefs.getString(key,"none");if(!Arrays.asList("none","cinema239","cinema235","cinema185","white","black").contains(frame))frame="none";xml.append("<string name='aabhix.").append(key).append("'>").append(frame).append("</string>");}xml.append("<int name='aabhix.iso' value='").append(camera.manualIso()).append("'/><string name='aabhix.exposureNs'>").append(camera.manualExposure()).append("</string><int name='aabhix.wb' value='").append(camera.whiteBalance()).append("'/><int name='aabhix.evSteps' value='").append(camera.manualIso()>0?0:camera.currentEv()).append("'/>");xml.append("</aabhix-config>");store("Aabhix setup "+new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.ROOT).format(new Date()),xml.toString());show();}catch(Exception e){error(e);}}
    private void error(Exception error){activity.runOnUiThread(()->error(error,0));}
    private void error(Exception error,int attempt){if(activity.isFinishing()||activity.isDestroyed())return;if(!activity.hasWindowFocus()){if(attempt<15)activity.getWindow().getDecorView().postDelayed(()->error(error,attempt+1),200);return;}new AlertDialog.Builder(activity).setTitle("Configuration not applied").setMessage(error.getMessage()).setPositiveButton("Close",null).show();}
}
